function fewestJumps(reach) {
  const last = reach.length - 1
  let jumps = 0
  let rangeEnd = 0
  let farthest = 0
  for (let i = 0; i < last; i++) {
    farthest = Math.max(farthest, i + reach[i])
    if (i === rangeEnd) {
      if (farthest <= i) return -1
      jumps++
      rangeEnd = farthest
      if (rangeEnd >= last) break
    }
  }
  return jumps
}

