def fewest_jumps(reach):
    last = len(reach) - 1
    jumps = range_end = farthest = 0
    for i in range(last):
        farthest = max(farthest, i + reach[i])
        if i == range_end:
            if farthest <= i:
                return -1
            jumps += 1
            range_end = farthest
            if range_end >= last:
                break
    return jumps
